input.command:
# Delete local non-main branches
git branch | ForEach-Object { $_.Trim() } | Where-Object { $_ -ne '* main' -and $_ -ne 'main' -and $_ -notlike '* main' } | ForEach-Object { $b = $_ -replace '^\* ', ''; if ($b -ne 'main') { Write-Host "Deleting local: $b"; git branch -D $b } }

# Collect remote branches except main and HEAD
$remoteBranches = git branch -r | ForEach-Object { $_.Trim() } | Where-Object { $_ -like 'origin/*' -and $_ -notlike 'origin/HEAD*' -and $_ -ne 'origin/main' } | ForEach-Object { $_ -replace '^origin/', '' }
Write-Host "Remote branches to delete:"; $remoteBranches
if ($remoteBranches) {
  git push origin --delete @($remoteBranches)
}
Write-Host '--- AFTER CLEANUP ---'
git fetch --prune
git branch -a
git status
git log -1 --oneline
